DROP FUNCTION IF EXISTS nexus.plain_search_384(nexus.vector, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.plain_search_768(nexus.vector, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.plain_search_1024(nexus.vector, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_384(nexus.vector, text, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_768(nexus.vector, text, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_hnsw_first_1024(nexus.vector, text, text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_by_chash_384(nexus.vector, bytea[], text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_by_chash_768(nexus.vector, bytea[], text[], jsonb, text, int);
DROP FUNCTION IF EXISTS nexus.text_gated_search_by_chash_1024(nexus.vector, bytea[], text[], jsonb, text, int);

CREATE OR REPLACE FUNCTION nexus.plain_search_384( p_query nexus.vector(384), p_collections text[], p_where jsonb, p_where_path text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m2 JOIN nexus.catalog_documents d2 ON d2.tenant_id = m2.tenant_id AND d2.tumbler = m2.doc_id WHERE m2.tenant_id = m.tenant_id AND m2.chash = m.chash AND d2.deleted_at IS NULL))) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.plain_search_768( p_query nexus.vector(768), p_collections text[], p_where jsonb, p_where_path text, p_n int ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.chash = c.chash AND d.deleted_at IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m2 JOIN nexus.catalog_documents d2 ON d2.tenant_id = m2.tenant_id AND d2.tumbler = m2.doc_id WHERE m2.tenant_id = m.tenant_id AND m2.chash = m.chash AND d2.deleted_at IS NULL))) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
